import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {compareDraft,resolveDraft,issueDraftValues} from '../../web/src/pages/work/issue-draft.js';
import {issueForm,issuePayload,changedFields} from '../../web/src/pages/work/issue-state.js';
async function fixture(run){const server=await testServer();try{const api=server.agent(),user=(await api('POST','/auth/signup',{name:'Draft owner',email:'draft@example.test',password:'correct-horse-battery'})).data.user,org=(await api('POST','/orgs',{name:'Draft org'})).data.organization,project=(await api('POST','/orgs/'+org.id+'/projects',{key:'DRAFT',name:'Draft project'})).data.project;await run({server,api,user,org,project});}finally{await server.close();}}
test('resolved issue fields preserve independent changes and a later race still rejects without mutation',()=>fixture(async({server,api,project})=>{
  const created=(await api('POST','/projects/'+project.id+'/issues',{title:'Before',description:'Before body',estimate:3})).data.issue;
  const sameTimestamp=()=>server.ctx.db.prepare('UPDATE issues SET updated_at=? WHERE id=?').run('2026-10-16T00:00:00.000Z',created.id);
  sameTimestamp();const baseline=(await api('GET','/issues/'+created.id)).data.issue,mine={...issueDraftValues(baseline),title:'Mine',description:'',estimate:''};
  assert.equal((await api('PATCH','/issues/'+baseline.id,{title:'Peer',priority:4,expectedRevision:baseline.revision})).status,200);
  sameTimestamp();const latest=(await api('GET','/issues/'+baseline.id)).data.issue;assert.equal(latest.updatedAt,baseline.updatedAt);assert.notEqual(latest.revision,baseline.revision);
  const comparison=compareDraft(issueDraftValues(baseline),mine,issueDraftValues(latest));assert.deepEqual(comparison.conflicts.map(field=>field.key),['title']);
  const resolved=issuePayload(resolveDraft(comparison,{title:'mine'})),body={...changedFields(issuePayload(issueForm(latest)),resolved),expectedRevision:latest.revision};
  assert.equal((await api('PATCH','/issues/'+baseline.id,{priority:2,expectedRevision:latest.revision})).status,200);
  sameTimestamp();const newer=(await api('GET','/issues/'+baseline.id)).data.issue,events=[];assert.equal(newer.updatedAt,baseline.updatedAt);server.ctx.bus.subscribe(event=>events.push(event));
  const rejected=await api('PATCH','/issues/'+baseline.id,body);assert.equal(rejected.status,409);assert.deepEqual(rejected.data.error.details.current,newer);assert.equal(events.length,0);assert.equal(mine.title,'Mine');
  const next=resolveDraft(compareDraft(issueDraftValues(latest),resolveDraft(comparison,{title:'mine'}),issueDraftValues(newer)));
  const saved=(await api('PATCH','/issues/'+baseline.id,{...changedFields(issuePayload(issueForm(newer)),issuePayload(next)),expectedRevision:newer.revision})).data.issue;
  assert.equal(saved.title,'Mine');assert.equal(saved.description,'');assert.equal(saved.estimate,null);assert.equal(saved.priority,2);
}));
test('label independent color and comment overlap resolution use existing authorized revision snapshots',()=>fixture(async({api,project,server})=>{
  const issue=(await api('POST','/projects/'+project.id+'/issues',{title:'Draft discussion'})).data.issue,label=(await api('POST','/projects/'+project.id+'/labels',{name:'Before',color:'#111111'})).data.label;
  const latest=(await api('PATCH','/labels/'+label.id,{color:'#222222',expectedRevision:label.revision})).data.label;
  const values=resolveDraft(compareDraft({name:label.name,color:label.color},{name:'Mine',color:label.color},{name:latest.name,color:latest.color}));
  const saved=(await api('PATCH','/labels/'+label.id,{...values,expectedRevision:latest.revision})).data.label;assert.equal(saved.name,'Mine');assert.equal(saved.color,'#222222');
  const comment=(await api('POST','/issues/'+issue.id+'/comments',{body:'Before'})).data.comment,newer=(await api('PATCH','/comments/'+comment.id,{body:'**Peer**',expectedRevision:comment.revision})).data.comment;
  const comparison=compareDraft({body:comment.body},{body:'**Mine**'},{body:newer.body});assert.throws(()=>resolveDraft(comparison));
  const response=await api('PATCH','/comments/'+comment.id,{...resolveDraft(comparison,{body:'mine'}),expectedRevision:newer.revision});assert.equal(response.data.comment.body,'**Mine**');assert.match(response.data.comment.html,/<strong>Mine<\/strong>/);
  const stranger=server.agent();assert.equal((await stranger('GET','/comments/'+comment.id)).status,401);
}));

import test from 'node:test';
import assert from 'node:assert/strict';
import {compareDraft,resolveDraft,discardDraft,issueDraftValues} from '../src/pages/work/issue-draft.js';
import {issuePayload,issueForm} from '../src/pages/work/issue-state.js';
test('three-way independent peer fields survive local null empty labels and Markdown changes',()=>{
  const before={title:'Original',description:'old',assigneeId:'person',estimate:3,parentId:'parent',dueDate:'2026-10-16',labelIds:['a'],priority:0};
  const mine={...before,description:'**mine**',assigneeId:null,estimate:null,parentId:null,dueDate:null,labelIds:[]},latest={...before,title:'Newer title',priority:4};
  const comparison=compareDraft(before,mine,latest);assert.equal(comparison.conflicts.length,0);assert.deepEqual(resolveDraft(comparison),{...mine,title:'Newer title',priority:4});
  assert.equal(resolveDraft(compareDraft({body:'before'},{body:''},{body:'before'})).body,'');
});
test('each overlapping field needs its own explicit choice and can independently keep mine or latest',()=>{
  const comparison=compareDraft({title:'before',body:'before',color:'#111111'},{title:'mine',body:'**mine**',color:'#111111'},{title:'latest',body:'**latest**',color:'#222222'});
  assert.deepEqual(comparison.conflicts.map(field=>field.key),['title','body']);assert.throws(()=>resolveDraft(comparison),/every overlapping/);assert.throws(()=>resolveDraft(comparison,{title:'mine'}),/body/);
  assert.deepEqual(resolveDraft(comparison,{title:'mine',body:'latest'}),{title:'mine',body:'**latest**',color:'#222222'});
});
test('equal results and equal snapshots need no conflict even when both sides changed',()=>{
  const comparison=compareDraft({title:'before',estimate:1},{title:'same',estimate:2},{title:'same',estimate:2});assert.equal(comparison.conflicts.length,0);assert.deepEqual(resolveDraft(comparison),{title:'same',estimate:2});
  assert.equal(compareDraft({title:'equal'},{title:'equal'},{title:'equal'}).dirty,false);
});
test('label membership comparison ignores order but requires a choice for different replacements',()=>{
  assert.equal(compareDraft({labelIds:['a','b']},{labelIds:['b','a']},{labelIds:['a','b']}).dirty,false);
  const comparison=compareDraft({labelIds:['a']},{labelIds:[]},{labelIds:['b']});assert.equal(comparison.conflicts.length,1);assert.deepEqual(resolveDraft(comparison,{labelIds:'mine'}).labelIds,[]);
});
test('issue form adapter reuses canonical payload clearing and excludes revision timestamps from field decisions',()=>{
  const before=issueDraftValues({title:'Original',description:'before',priority:2,estimate:4,labels:[{id:'a'}],updatedAt:'same',revision:'old'});
  const mine={...before,title:'Mine',description:'',estimate:'',labelIds:[]},latest=issueDraftValues({title:'Peer',description:'before',priority:4,estimate:4,labels:[{id:'a'}],updatedAt:'same',revision:'new'});
  const comparison=compareDraft(before,mine,latest);assert.deepEqual(comparison.conflicts.map(field=>field.key),['title']);const resolved=issuePayload(resolveDraft(comparison,{title:'mine'}));assert.equal(resolved.estimate,null);assert.equal(resolved.description,'');assert.deepEqual(resolved.labelIds,[]);assert.equal(resolved.priority,4);assert.ok(!('revision' in resolved));
});
test('dirty cancel invokes an explicit discard decision and unchanged forms close without asking',()=>{
  let calls=0;const reject=()=>{calls++;return false;};assert.equal(discardDraft({body:''},{body:''},reject),true);assert.equal(calls,0);
  assert.equal(discardDraft({body:''},{body:'draft'},reject),false);assert.equal(calls,1);assert.equal(discardDraft({body:''},{body:'draft'},()=>true),true);
});
test('comparison and failed resolution preserve original baseline draft and latest snapshots',()=>{
  const before=Object.freeze({body:'before'}),mine=Object.freeze({body:'mine'}),latest=Object.freeze({body:'latest'});const comparison=compareDraft(before,mine,latest);assert.throws(()=>resolveDraft(comparison,{body:'guess'}));assert.deepEqual(before,{body:'before'});assert.deepEqual(mine,{body:'mine'});assert.deepEqual(latest,{body:'latest'});assert.deepEqual(comparison.fields[0],{key:'body',before:'before',mine:'mine',latest:'latest',localChanged:true,peerChanged:true,conflict:true});
});
test('a live issueForm draft uses edited labelIds rather than its retained baseline label records',()=>{
  const baseline={title:'Before',labels:[{id:'a',name:'Original'}]},form=issueForm(baseline);form.labelIds=['a','new'];
  const values=issueDraftValues(form);assert.deepEqual(values.labelIds,['a','new']);
  const latest={...baseline,priority:4},resolved=resolveDraft(compareDraft(issueDraftValues(baseline),values,issueDraftValues(latest)));
  assert.deepEqual(issuePayload(resolved).labelIds,['a','new']);form.labelIds=[];assert.deepEqual(issueDraftValues(form).labelIds,[]);
});
